                    Card tmp = a[j];
                    a[j] = a[j - 1];
                    a[j - 1] = tmp;
                }
            }
        }
    }

    static void selectionSort(Card[] a) {
        int n = a.length;
        for (int i = 0; i < n; i++) {
            int minj = i;
            for (int j = i; j < n; j++) {
                if (a[j].value < a[minj].value) {
                    minj = j;
                }
            }
            Card tmp = a[i];
            a[i] = a[minj];
            a[minj] = tmp;
        }
    }

    static boolean isStable(Card[] original, Card[] sorted) {
        Map<Integer, List<Character>> mapOriginal = new HashMap<>();
        Map<Integer, List<Character>> mapSorted = new HashMap<>();

        for (Card c : original) {
            mapOriginal.computeIfAbsent(c.value, k -> new ArrayList<>()).add(c.suit);
        }
        for (Card c : sorted) {
            mapSorted.computeIfAbsent(c.value, k -> new ArrayList<>()).add(c.suit);
        }

        for (int key : mapOriginal.keySet()) {
            List<Character> o = mapOriginal.get(key);
            List<Character> s = mapSorted.get(key);
            if (s == null || o.size() != s.size()) return false;
            for (int i = 0; i < o.size(); i++) {
                if (!o.get(i).equals(s.get(i))) return false;
            }
        }
        return true;
    }

    static void printCards(Card[] a, PrintWriter out) {
        for (int i = 0; i < a.length; i++) {
            if (i > 0) out.print(" ");
            out.print(a[i]);
        }
        out.println();
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = fs.nextInt();
        Card[] original = new Card[n];
        Card[] bubble = new Card[n];
        Card[] selection = new Card[n];

        for (int i = 0; i < n; i++) {
            String s = fs.next();
            char suit = s.charAt(0);
            int value = Integer.parseInt(s.substring(1));
            original[i] = new Card(suit, value);
            bubble[i] = new Card(suit, value);
            selection[i] = new Card(suit, value);
        }

        bubbleSort(bubble);
        selectionSort(selection);

        printCards(bubble, out);
        out.println("Stable");
        printCards(selection, out);
        out.println(isStable(original, selection) ? "Stable" : "Not stable");

        out.flush();
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && Character.isWhitespace(c));
            while (c != -1 && !Character.isWhitespace(c)) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
